// WF11 Social Source Connector Foundation config — Telegram PUBLIC channel preview (t.me/s/<channel>).
// Deterministic ids; MSK timestamps; NO external calls in this workflow (fixture-first, DEC-110).
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const now=moscowIsoNow();
const stamp=moscowStamp();
return [{ json: {
  fixture_mode:true,
  live_mode:false,
  // --- live v0.2 GUARDED PATH (DEC-116/120): live preview fetch path exists but is INERT by default —
  // live_mode=false, approval token empty, allowlist empty, and the HTTP node is DISABLED in the editor.
  // Enabling live requires ALL of: explicit operator approval (token), allowlist, enabling the HTTP node.
  // Scope is hard-limited: PUBLIC t.me/s/<channel> preview pages only — no groups, no private chats,
  // no MTProto/client sessions, no login, no member extraction, no hidden contacts, no auto-outreach.
  live_transport:'http_get_t_me_preview',
  live_channel_allowlist:[],
  live_max_posts_per_channel:10,
  live_approval_token:'',
  live_requires_operator_approval:true,
  source_type:'social_channel',
  platform:'telegram',
  requested_by:'operator',
  request_type:'social_source_discovery',
  region:'Москва/МО',
  service_focus:'credit_broker',
  channel_allowlist:[
    'kredit_broker_msk_fixture',
    'ipoteka_refinance_fixture',
    'finance_news_fixture',
    'biz_uslugi_fixture'
  ],
  preview_url_template:'https://t.me/s/<channel>',
  pipeline_limit:10,
  include_irrelevant_control_fixture:true,
  approval_status_for_unique:'new',
  write_duplicate_audit:true,
  hard_skip_debug_audit:false,
  duplicate_next_action:'monitor_duplicate',
  spreadsheet_id_placeholder:'PASTE_SPREADSHEET_ID',
  agent_request_id:'wf11_req_'+stamp,
  run_id:'wf11_'+stamp,
  created_at:now
}}];

// LIVE PREVIEW APPROVAL GATE (DEC-116/120) — fires on live_mode=true. INERT BY DEFAULT: it throws unless
// the operator has explicitly armed the run. Even when armed, the downstream HTTP node ships DISABLED, so
// no network call can happen without a second deliberate operator action in the n8n editor.
// Hard scope (CONTACT_AND_OUTREACH_POLICY): PUBLIC t.me/s/<channel> preview pages ONLY — no groups, no
// private chats, no MTProto/sessions, no login scraping, no member extraction, no hidden contacts, no outreach.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Connector Config').first().json;
const token=str(cfg.live_approval_token);
const allow=Array.isArray(cfg.live_channel_allowlist)?cfg.live_channel_allowlist.map(c=>str(c)).filter(Boolean):[];
const maxPosts=Math.min(Number(cfg.live_max_posts_per_channel)||10,10);
if(token!=='I_APPROVE_LIVE_TELEGRAM_PREVIEW'){
  throw new Error('WF11 live gate: operator approval token missing. Live Telegram public-channel preview requires explicit operator approval: set live_approval_token=I_APPROVE_LIVE_TELEGRAM_PREVIEW, fill live_channel_allowlist, then ENABLE the disabled HTTP node. Default run stays fixture-only ($0). See docs/N8N_WORKFLOW_11_SOCIAL_SOURCE_CONNECTOR_FOUNDATION_RU.md and STAGE_3_4 §5.7.');
}
if(!allow.length){ throw new Error('WF11 live gate: live_channel_allowlist is empty — allowlist-only operation, no discovery crawling.'); }
const bad=allow.filter(c=>/[^a-zA-Z0-9_]/.test(c)||/joinchat/i.test(c)||c.charAt(0)==='+');
if(bad.length){ throw new Error('WF11 live gate: rejected non-public-channel entries (groups/invite links/private are forbidden): '+bad.join(', ')); }
// one item per allowlisted channel; the (disabled) HTTP node would GET the PUBLIC preview page only.
return allow.map(c=>({ json: { channel:c, fetch_url:'https://t.me/s/'+c, max_posts:maxPosts, live_transport:str(cfg.live_transport) } }));

// Normalize Telegram public-channel preview posts into the WF09-compatible record shape. Deterministic, $0.
// Contact policy (DEC-097/098): contact_public is copied ONLY when visible verbatim in the public post text;
// the post_url is the contact evidence; nothing is reconstructed; channel-ad records are aggregate/monitor data.
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
function hashText(s){s=str(s);let h=5381;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return ('00000000'+h.toString(16)).slice(-8);}
function canonPostUrl(u){u=str(u);return u.replace(/[?#].*$/,'').replace(/\/+$/,'');}
const cfg=$('Set Connector Config').first().json;
// v0.2 (DEC-120): read from $input so BOTH branches feed normalization — fixture posts (default) or
// live-preview parsed posts (guarded, inert by default). Same post shape, same counters in fixture mode.
const items=$input.all().map(i=>i.json);
// niche vocabulary v0.1 hardcoded (credit_brokerage) — migrates to niche packs (DEC-100)
const STRONG=['кредитный брокер','ипотечный брокер','помощь в получении кредита','помощь с кредитом','кредит после отказов','после отказов','плохой кредитной историей','плохая кредитная история','кредит для бизнеса','оборотные','тендерные займ','банковские гарантии','рефинансирование','снижение ставки','одобрение кредита','подбор банка'];
const WEAK=['кредит','займ','банк','отказ','скоринг','ставк','заёмщик','ипотек','финанс'];
const HARD_NEG=['юридический адрес','регистрация ооо','регистрация ип','бухгалтер','эквайринг','pos-терминал','касса','печать и штамп','эцп','аренда офиса','коворкинг'];
const KW=[['кредитный брокер','кредитный брокер'],['после отказов','после отказов'],['плох','плохая кредитная история'],['без предоплаты','без предоплаты'],['оплата за результат','оплата за результат'],['по договору','работа по договору'],['для бизнеса','бизнес-кредит'],['оборотные','оборотные кредиты'],['тендерн','тендерные займы'],['банковские гарант','банковские гарантии'],['рефинансир','рефинансирование'],['снижение ставк','снижение ставки'],['за 1 день','скорость'],['комиссия от','ценовой якорь']];
const out=[];
for(const p of items){
  const channel=str(p.channel);const postId=str(p.post_id);const text=str(p.text);
  const blob=low(text)+' '+low(p.channel_title);
  const valid=!!(channel&&postId&&text.length>=30);
  const strongHit=STRONG.filter(t=>blob.indexOf(t)>=0);
  const weakHit=WEAK.filter(t=>blob.indexOf(t)>=0);
  const negHit=HARD_NEG.filter(t=>blob.indexOf(t)>=0);
  let record_type_hint='irrelevant';let predicted_entity_type='irrelevant';let predicted_route='skipped_log';
  let confidence=10;let hard_skip=false;let relevance_reason='';
  if(!valid){ relevance_reason='invalid: missing channel/post_id or text<30'; }
  else if(negHit.length&&!strongHit.length){ hard_skip=true; relevance_reason='hard negative: '+negHit.join(', '); }
  else if(strongHit.length){ record_type_hint='competitor_activity';predicted_entity_type='competitor';predicted_route='monitor_queue';confidence=70;relevance_reason='strong: '+strongHit.slice(0,4).join(', '); }
  else if(weakHit.length>=2){ record_type_hint='market_signal';predicted_entity_type='market_signal';predicted_route='content_queue';confidence=45;relevance_reason='weak finance: '+weakHit.slice(0,4).join(', '); }
  else { hard_skip=true; relevance_reason='no niche evidence'; }
  // public contact: verbatim @handle or +7 phone visible in the post text only — never reconstructed.
  // contact_channel is a CHANNEL CATEGORY (phone/email/telegram/profile/form/unknown — DEC-114), never a format:
  // a Telegram @handle gets contact_channel='telegram'; the format ('handle') goes to notes via contact_format.
  let contact='';let contactChannel='';let contactFormat='';
  const h=text.match(/@[a-zA-Z0-9_]{5,32}/);
  const ph=text.match(/(?:\+7|8)[\s\-(]*\d{3}[\s\-)]*\d{3}[\s\-]*\d{2}[\s\-]*\d{2}/);
  if(ph){contact=ph[0];contactChannel='phone';contactFormat='phone';}
  else if(h){contact=h[0];contactChannel='telegram';contactFormat='handle';}
  const kws=[];const seen={};for(const k of KW){if(blob.indexOf(k[0])>=0&&!seen[k[1]]){seen[k[1]]=1;kws.push(k[1]);}}
  let service='unknown';
  if(blob.indexOf('ипотек')>=0||blob.indexOf('рефинансир')>=0)service='mortgage_refinance';
  else if(blob.indexOf('для бизнеса')>=0||blob.indexOf('оборотные')>=0||blob.indexOf('тендерн')>=0)service='business_credit';
  else if(blob.indexOf('после отказов')>=0||blob.indexOf('отказ')>=0)service='credit_after_refusals';
  if(blob.indexOf('кредитный брокер')>=0)service='credit_broker';
  const canon=canonPostUrl(p.post_url)||('https://t.me/'+channel+'/'+postId);
  out.push({ json: {
    is_valid_listing:valid,
    hard_skip:hard_skip,
    relevance_reason:relevance_reason,
    source_type:str(cfg.source_type)||'social_channel',
    platform:str(cfg.platform)||'telegram',
    source_url:'https://t.me/s/'+channel,
    post_url:canon,
    profile_url:'https://t.me/'+channel,
    profile_name:str(p.channel_title)||channel,
    author_handle:'@'+channel,
    published_at:str(p.published_at),
    region_hint:(blob.indexOf('москв')>=0?'Москва/МО':''),
    service_hint:service,
    query:'allowlist:'+channel,
    text_context:cut(text,3500),
    comment_text:'',
    contact_public:contact,
    contact_channel:contactChannel,
    contact_format:contactFormat,
    dedup_key:'telegram::social_channel::'+canon,
    text_hash:hashText(low(text)),
    record_type_hint:record_type_hint,
    touchpoint_type:(record_type_hint==='competitor_activity')?'public_channel_post':(record_type_hint==='market_signal'?'public_channel_post':'irrelevant_source'),
    lead_intent_hint:'none',
    urgency_hint:'none',
    interest_topic:(record_type_hint==='competitor_activity')?'competitor channel ad copy':(record_type_hint==='market_signal'?'market context':''),
    probable_need:'',
    competitor_related:(record_type_hint==='competitor_activity'),
    competitor_name:(record_type_hint==='competitor_activity')?(str(p.channel_title)||channel):'',
    semantic_keywords:kws.join(', '),
    ad_channel_hint:'telegram',
    confidence_score:confidence,
    lead_temperature:'none',
    next_action:'monitor',
    responsible:'operator',
    estimated_analysis_cost_usd:0,
    manager_note:'',
    predicted_route:predicted_route,
    predicted_entity_type:predicted_entity_type,
    contact_evidence_url:contact?canon:'',
    notes:''
  }});
}
return out;

// Dedup normalized posts vs market_record_registry (by dedup_key) + within batch. No external calls.
// Mirrors the proven WF09 pattern: invalid and hard-skipped items never register, never count unique,
// never consume the pipeline cap; hard skips apply in BOTH modes (fixture control demonstrates the filter).
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Connector Config').first().json;
const approvalUnique=str(cfg.approval_status_for_unique)||'new';
const dupNext=str(cfg.duplicate_next_action)||'monitor_duplicate';
const pipelineLimit=Number(cfg.pipeline_limit)||10;
const recs=$('Normalize Telegram Posts').all().map(i=>i.json);
let reg=[];
try{reg=$('Read market_record_registry').all().map(i=>i.json).filter(Boolean);}catch(e){reg=[];}
const regSet=new Set(reg.map(r=>str(r&&r.dedup_key)).filter(Boolean));
const seen=new Set();
const out=[];
let acceptedCount=0;
for(const r of recs){
  if(r.is_valid_listing===false){
    out.push({ json: Object.assign({}, r, { dedup_status:'invalid', approval_status:'invalid', next_action:'ignore' }) });
    continue;
  }
  if(r.hard_skip===true){
    out.push({ json: Object.assign({}, r, { dedup_status:'hard_skipped', approval_status:'skipped_irrelevant', next_action:'ignore' }) });
    continue;
  }
  if(acceptedCount>=pipelineLimit){
    out.push({ json: Object.assign({}, r, { dedup_status:'over_pipeline_limit', approval_status:'skipped', next_action:'ignore' }) });
    continue;
  }
  acceptedCount++;
  const key=str(r.dedup_key);
  let dedup_status='unique';
  let approval_status=approvalUnique;
  let next_action=str(r.next_action);
  if(key&&regSet.has(key)){
    dedup_status='duplicate_in_registry';approval_status='duplicate';next_action=dupNext;
  } else if(key&&seen.has(key)){
    dedup_status='duplicate_in_batch';approval_status='duplicate';next_action=dupNext;
  } else {
    dedup_status='unique';if(key)seen.add(key);
  }
  out.push({ json: Object.assign({}, r, { dedup_status:dedup_status, approval_status:approval_status, next_action:next_action }) });
}
return out;

// Build raw_market_records rows (exactly 40 columns, matching WF07/WF09 schema). No external calls.
function str(v){return v==null?'':String(v).trim();}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const cfg=$('Set Connector Config').first().json;
const reqId=str(cfg.agent_request_id);
const created=str(cfg.created_at);
const stamp=str(cfg.run_id).replace(/^wf11_/,'')||moscowStamp();
const writeDupAudit=(cfg.write_duplicate_audit===true||str(cfg.write_duplicate_audit).toLowerCase()==='true');
const hardDebug=(cfg.hard_skip_debug_audit===true||str(cfg.hard_skip_debug_audit).toLowerCase()==='true');
const recs=$('Deduplicate Posts').all().map(i=>i.json);
const out=[];let idx=0;
for(const r of recs){
  idx++;
  const ds0=str(r.dedup_status);
  if(ds0==='invalid'||ds0==='over_pipeline_limit')continue;
  if(ds0==='hard_skipped'&&!hardDebug)continue;
  if(!writeDupAudit && ds0!=='unique')continue;
  // contact policy: contact format + evidence URL are recorded in notes (no dedicated columns in the 40-col schema yet)
  let notes='stage_3_4_telegram_public_channel_preview_connector_foundation';
  if(str(r.contact_public)){ notes+='; contact_format='+(str(r.contact_format)||'unknown')+'; contact_source_url='+str(r.contact_evidence_url)+'; contact_use_policy=manual_review (CONTACT_AND_OUTREACH_POLICY)'; }
  out.push({ json: {
    record_id:'wf11_rec_'+stamp+'_'+idx,
    agent_request_id:reqId,
    created_at:created,
    source_type:str(r.source_type),
    platform:str(r.platform),
    source_url:str(r.source_url),
    post_url:str(r.post_url),
    profile_url:str(r.profile_url),
    profile_name:str(r.profile_name),
    author_handle:str(r.author_handle),
    published_at:str(r.published_at),
    region_hint:str(r.region_hint),
    service_hint:str(r.service_hint),
    query:str(r.query),
    text_context:str(r.text_context),
    comment_text:str(r.comment_text),
    contact_public:str(r.contact_public),
    contact_channel:str(r.contact_channel),
    dedup_key:str(r.dedup_key),
    record_type_hint:str(r.record_type_hint),
    touchpoint_type:str(r.touchpoint_type),
    lead_intent_hint:str(r.lead_intent_hint),
    urgency_hint:str(r.urgency_hint),
    interest_topic:str(r.interest_topic),
    probable_need:str(r.probable_need),
    competitor_related:(r.competitor_related===true||str(r.competitor_related).toLowerCase()==='true'),
    competitor_name:str(r.competitor_name),
    semantic_keywords:str(r.semantic_keywords),
    ad_channel_hint:str(r.ad_channel_hint),
    confidence_score:Number(r.confidence_score)||0,
    lead_temperature:str(r.lead_temperature),
    next_action:str(r.next_action),
    responsible:str(r.responsible),
    dedup_status:str(r.dedup_status),
    approval_status:str(r.approval_status),
    approved_by:'',
    approved_at:'',
    estimated_analysis_cost_usd:Number(r.estimated_analysis_cost_usd)||0,
    manager_note:str(r.manager_note),
    notes:notes
  }});
}
return out;

// Build market_record_registry rows for UNIQUE records only (exactly 15 columns). No external calls.
function str(v){return v==null?'':String(v).trim();}
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
const now=moscowIsoNow();
const recs=$('Deduplicate Posts').all().map(i=>i.json);
const out=[];
for(const r of recs){
  if(str(r.dedup_status)!=='unique')continue;
  out.push({ json: {
    dedup_key:str(r.dedup_key),
    source_type:str(r.source_type),
    platform:str(r.platform),
    source_url:str(r.source_url),
    post_url:str(r.post_url),
    profile_url:str(r.profile_url),
    author_handle:str(r.author_handle),
    text_hash:str(r.text_hash),
    first_seen_at:now,
    last_seen_at:now,
    last_route:str(r.predicted_route),
    last_processing_status:'raw_collected',
    last_entity_type:str(r.predicted_entity_type),
    agent_request_id:str($('Set Connector Config').first().json.agent_request_id),
    note:'telegram_public_channel_preview_connector_foundation_stage_3_4'
  }});
}
return out;

// One agent_requests row (exactly 21 columns). status=completed. No external calls.
function str(v){return v==null?'':String(v).trim();}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
const cfg=$('Set Connector Config').first().json;
const recs=$('Deduplicate Posts').all().map(i=>i.json);
const posts_received=recs.length;
const invalid_items=recs.filter(r=>str(r.dedup_status)==='invalid').length;
const structurally_valid_items=posts_received-invalid_items;
const hard_skipped_items=recs.filter(r=>str(r.dedup_status)==='hard_skipped').length;
const business_relevant_items=structurally_valid_items-hard_skipped_items;
const over_pipeline_limit=recs.filter(r=>str(r.dedup_status)==='over_pipeline_limit').length;
const unique=recs.filter(r=>str(r.dedup_status)==='unique').length;
const duplicate=recs.filter(r=>str(r.dedup_status).indexOf('duplicate')===0).length;
const fixtureMode=(cfg.fixture_mode===true||str(cfg.fixture_mode).toLowerCase()==='true');
const channels=Array.isArray(cfg.channel_allowlist)?cfg.channel_allowlist.join(', '):'';
let notes='WF11 foundation (DEC-110): Telegram PUBLIC channel preview connector, fixture-first, no external calls, no MTProto/groups/private chats. No auto-handoff to WF08. Source: '+(fixtureMode?'fixture':'live_preview')+'. Contact policy: public contacts verbatim from post text only, evidence URL in raw notes, default manual_review.';
if(hard_skipped_items>0){
  const firstHard=recs.filter(r=>str(r.dedup_status)==='hard_skipped')[0];
  notes+=' hard_skipped_items='+hard_skipped_items+' (hard-negative/no-evidence posts filtered before raw/registry).';
  if(firstHard){ notes+=' first_hard_skip: '+cut(str(firstHard.post_url),80)+' ['+cut(str(firstHard.relevance_reason),120)+']'; }
}
return [{ json: {
  agent_request_id:str(cfg.agent_request_id),
  created_at:str(cfg.created_at),
  requested_by:str(cfg.requested_by)||'operator',
  request_text:'Telegram public channel preview discovery (allowlist): '+channels,
  request_type:str(cfg.request_type)||'social_source_discovery',
  source_scope:'social_public',
  platforms:'telegram',
  query:'allowlist: '+channels,
  region:str(cfg.region)||'Москва/МО',
  service_focus:str(cfg.service_focus)||'credit_broker',
  requested_limit:Number(cfg.pipeline_limit)||10,
  status:'completed',
  plan_summary:'WF11 Telegram public-channel preview connector ('+(fixtureMode?'fixture mode':'live preview mode')+') -> raw_market_records + market_record_registry for the Touchpoint Analyzer (Workflow 08). One source at a time (DEC-096).',
  estimated_source_cost_usd:0,
  estimated_analysis_cost_usd:0,
  approval_required:false,
  approved_by:'',
  approved_at:'',
  result_summary:'posts_received='+posts_received+'; structurally_valid_items='+structurally_valid_items+'; invalid_items='+invalid_items+'; business_relevant_items='+business_relevant_items+'; hard_skipped_items='+hard_skipped_items+'; unique='+unique+'; duplicates='+duplicate+'; over_pipeline_limit='+over_pipeline_limit+'.',
  next_action:(unique>0?'Inspect raw_market_records, then run Workflow 08 manually with agent_request_id_filter. No auto-handoff, no outreach (DEC-098).':'No unique business-relevant posts: review fixtures/allowlist; do NOT run Workflow 08.'),
  notes:notes
}}];

// Final run summary. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Connector Config').first().json;
const recs=$('Deduplicate Posts').all().map(i=>i.json);
const posts_received=recs.length;
const invalid_items=recs.filter(r=>str(r.dedup_status)==='invalid').length;
const structurally_valid_items=posts_received-invalid_items;
const hard_skipped_items=recs.filter(r=>str(r.dedup_status)==='hard_skipped').length;
const business_relevant_items=structurally_valid_items-hard_skipped_items;
const over_pipeline_limit=recs.filter(r=>str(r.dedup_status)==='over_pipeline_limit').length;
const unique=recs.filter(r=>str(r.dedup_status)==='unique').length;
const duplicate=recs.filter(r=>str(r.dedup_status).indexOf('duplicate')===0).length;
const writeDupAudit=(cfg.write_duplicate_audit===true||str(cfg.write_duplicate_audit).toLowerCase()==='true');
const rawWritten=writeDupAudit?(unique+duplicate):unique;
const record_type_counts={};
for(const r of recs){
  if(['invalid','over_pipeline_limit','hard_skipped'].indexOf(str(r.dedup_status))>=0)continue;
  const t=str(r.record_type_hint)||'unknown';record_type_counts[t]=(record_type_counts[t]||0)+1;
}
return [{ json: {
  workflow:'11 - Social Source Connector Foundation (Telegram Public Channel Preview)',
  agent_request_id:str(cfg.agent_request_id),
  run_id:str(cfg.run_id),
  fixture_mode:(cfg.fixture_mode===true||str(cfg.fixture_mode).toLowerCase()==='true'),
  live_mode:(cfg.live_mode===true||str(cfg.live_mode).toLowerCase()==='true'),
  posts_received:posts_received,
  structurally_valid_items:structurally_valid_items,
  invalid_items:invalid_items,
  business_relevant_items:business_relevant_items,
  hard_skipped_items:hard_skipped_items,
  over_pipeline_limit:over_pipeline_limit,
  unique_count:unique,
  duplicate_count:duplicate,
  raw_market_records_written:rawWritten,
  registry_rows_written:unique,
  record_type_counts:record_type_counts,
  source_cost_usd:0,
  next_action:(unique>0?'Inspect raw_market_records, then run Workflow 08 (Touchpoint Analyzer) manually with agent_request_id_filter. No auto-handoff, no outreach.':'No unique business-relevant posts: review fixtures/allowlist; do NOT run Workflow 08.')
}}];

// PARSE LIVE PREVIEW POSTS (inert until the HTTP placeholder is enabled by the operator).
// With the HTTP node disabled, items pass through WITHOUT an html body — this node then throws,
// guaranteeing no fabricated posts can enter the pipeline.
function str(v){return v==null?'':String(v).trim();}
const out=[];
for(const it of $input.all()){
  const j=it.json;
  const html=str(j.data||j.body||j.html);
  if(!html){
    throw new Error('WF11 live parse: no HTML received — the HTTP placeholder node is DISABLED (inert by design, DEC-120). Enable it only after operator approval; default runs use fixture mode.');
  }
  const channel=str(j.channel)||'unknown';
  const maxPosts=Math.min(Number(j.max_posts)||10,10);
  // t.me/s preview page: each post is a tgme_widget_message block with data-post="<channel>/<id>".
  const blocks=html.split('tgme_widget_message_wrap').slice(1);
  let count=0;
  for(const b of blocks){
    if(count>=maxPosts)break;
    const idm=b.match(/data-post="([^"\/]+)\/(\d+)"/);
    const txtm=b.match(/tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/);
    const timem=b.match(/datetime="([^"]+)"/);
    const titlem=b.match(/tgme_widget_message_owner_name[^>]*><span[^>]*>([\s\S]*?)<\/span>/);
    if(!idm||!txtm)continue;
    const text=txtm[1].replace(/<br\s*\/?>/gi,' ').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/\s+/g,' ').trim();
    if(!text)continue;
    count++;
    out.push({ json: { channel:idm[1], channel_title:titlem?titlem[1].replace(/<[^>]+>/g,'').trim():idm[1], post_id:idm[2], post_url:'https://t.me/'+idm[1]+'/'+idm[2], published_at:timem?timem[1]:'', text:text } });
  }
}
if(!out.length){ throw new Error('WF11 live parse: 0 posts parsed from preview HTML — check channel allowlist / page structure before retrying.'); }
return out;
